def _do_request(self, method: str, path: str, headers: dict[str, str], body: bytes | None = None) -> tuple[int, dict[str, str], bytes]:
    """Low-level HTTP request using http.client."""
    parsed = urlparse(self._base_url + path)
    use_ssl = parsed.scheme == "https"
    port = parsed.port or (443 if use_ssl else 80)

    cls = HTTPSConnection if use_ssl else HTTPConnection
    conn = cls(parsed.hostname, port, timeout=self._timeout)

    try:
        conn.request(method, parsed.path + parsed.query, body=body, headers=headers)
        resp = conn.getresponse()
        resp_body = resp.read()
        resp_headers = dict(resp.getheaders())
        return resp.status, resp_headers, resp_body
