from unittest.mock import Mock, patch

from vendorsync.meridian import MeridianClient


class FakeResponse:
    """Fake HTTP response for http.client mocking."""

    def __init__(self, status, body=None, headers=None):
        self.status = status
        self.body = body if isinstance(body, bytes) else (json.dumps(body).encode() if body is not None else b"")
        self._headers = dict(headers or {})

    def read(self):
        return self.body

    def getheaders(self):
        return list(self._headers.items())


class FakeConnection:
    """Fake HTTP connection that returns controlled responses."""

    def __init__(self, hostname, port=None, timeout=None):
        self.hostname = hostname
        self.port = port
        self.timeout = timeout
        self._last_request = None

    def request(self, method, url, body=None, headers=None):
        self._last_request = {"method": method, "url": url, "body": body, "headers": dict(headers or {})}

    def getresponse(self):
        raise NotImplementedError("Subclass must implement")

    def close(self):
        pass

    @property
    def last_request(self):
        return self._last_request


class TestMeridianClient(unittest.TestCase):

    def setUp(self):
        self.client = MeridianClient(
            base_url="http://127.0.0.1:8930",
            api_key="sk_test_meridian",
        )

    # ------------------------------------------------------------------
    # 1. test_fetch_all_payments_follows_cursor
    # ------------------------------------------------------------------
    def test_fetch_all_payments_follows_cursor(self):
        page1 = {
            "data": [{"id": f"p{i}", "amount_minor": i * 100, "currency": "EUR",
                      "created_at": "2026-01-01T00:00:0{i}Z", "status": "captured"}
                     for i in range(1, 3)],
            "next_cursor": "c1",
            "total": 5,
        }
        page2 = {
            "data": [{"id": f"p{i}", "amount_minor": i * 100, "currency": "EUR",
                      "created_at": "2026-01-01T00:00:0{i}Z", "status": "captured"}
                     for i in range(3, 5)],
            "next_cursor": "c2",
            "total": 5,
        }
        page3 = {
            "data": [{"id": f"p{i}", "amount_minor": i * 100, "currency": "EUR",
                      "created_at": "2026-01-01T00:00:0{i}Z", "status": "captured"}
                     for i in range(5, 6)],
            "next_cursor": None,
            "total": 5,
        }

        calls = iter([page1, page2, page3])

        class Conn(FakeConnection):
            def getresponse(self):
                body = next(calls)
                return FakeResponse(200, body=body)

        with patch("vendorsync.meridian.HTTPConnection", Conn):
            result = self.client.fetch_all_payments()

        self.assertEqual(len(result), 5)
        ids = [p["id"] for p in result]
        self.assertEqual(ids, ["p1", "p2", "p3", "p4", "p5"])

    # ------------------------------------------------------------------
    # 2. test_fetch_all_payments_410_recovery
    # ------------------------------------------------------------------
    def test_fetch_all_payments_410_recovery(self):
        page1_ok = {
            "data": [{"id": "p1", "amount_minor": 100, "currency": "EUR",
                      "created_at": "2026-01-01T00:00:01Z", "status": "captured"}],
            "next_cursor": "c1",
            "total": 3,
        }
        page410_body = json.dumps({"error": "cursor_expired"}).encode()

        page1_retry = {
            "data": [{"id": "p1", "amount_minor": 100, "currency": "EUR",
                      "created_at": "2026-01-01T00:00:01Z", "status": "captured"},
                     {"id": "p2", "amount_minor": 200, "currency": "EUR",
                      "created_at": "2026-01-01T00:00:02Z", "status": "captured"}],
            "next_cursor": "c_new",
            "total": 3,
        }
        page2_retry = {
            "data": [{"id": "p3", "amount_minor": 300, "currency": "EUR",
                      "created_at": "2026-01-01T00:00:03Z", "status": "captured"}],
            "next_cursor": None,
            "total": 3,
        }

        calls = iter([page1_ok, "410", page1_retry, page2_retry])

        class Conn(FakeConnection):
            def getresponse(self):
                val = next(calls)
                if val == "410":
                    return FakeResponse(410, body=page410_body)
                return FakeResponse(200, body=val)

        with patch("vendorsync.meridian.HTTPConnection", Conn):
            result = self.client.fetch_all_payments()

        self.assertEqual(len(result), 3)
        ids = [p["id"] for p in result]
        self.assertEqual(ids, ["p1", "p2", "p3"])

    # ------------------------------------------------------------------
    # 3. test_fetch_all_payments_429_retry_integer
    # ------------------------------------------------------------------
    def test_fetch_all_payments_429_retry_integer(self):
        ok_page = {
            "data": [{"id": "p1", "amount_minor": 100, "currency": "EUR",
                      "created_at": "2026-01-01T00:00:01Z", "status": "captured"}],
            "next_cursor": None,
            "total": 1,
        }

        call_count = [0]
        sleep_mock = Mock()

        class Conn(FakeConnection):
            def getresponse(self):
                call_count[0] += 1
                if call_count[0] == 1:
                    return FakeResponse(429, body={"error": "rate_limited"},
                                        headers={"Retry-After": "0"})
                return FakeResponse(200, body=ok_page)

        with patch("vendorsync.meridian.HTTPConnection", Conn):
            with patch("time.sleep", sleep_mock):
                result = self.client.fetch_all_payments()

        self.assertEqual(len(result), 1)
        self.assertEqual(result[0]["id"], "p1")
        self.assertTrue(sleep_mock.called)

    # ------------------------------------------------------------------
    # 4. test_fetch_all_payments_429_retry_http_date
    # ------------------------------------------------------------------
    def test_fetch_all_payments_429_retry_http_date(self):
        ok_page = {
            "data": [{"id": "p1", "amount_minor": 100, "currency": "EUR",
                      "created_at": "2026-01-01T00:00:01Z", "status": "captured"}],
            "next_cursor": None,
            "total": 1,
        }

        call_count = [0]
        sleep_mock = Mock()

        class Conn(FakeConnection):
            def getresponse(self):
                call_count[0] += 1
                if call_count[0] == 1:
                    return FakeResponse(429, body={"error": "rate_limited"},
                                        headers={"Retry-After": "Wed, 03 Aug 2026 15:00:00 GMT"})
                return FakeResponse(200, body=ok_page)

        with patch("vendorsync.meridian.HTTPConnection", Conn):
            with patch("time.sleep", sleep_mock):
                result = self.client.fetch_all_payments()

        self.assertEqual(len(result), 1)
        self.assertTrue(sleep_mock.called)
        # The HTTP-date is in the future, so sleep duration should be positive.
        arg = sleep_mock.call_args[0][0]
        self.assertGreater(arg, 0)

    # ------------------------------------------------------------------
    # 5. test_fetch_all_payments_etag_304
    # ------------------------------------------------------------------
    def test_fetch_all_payments_etag_304(self):
        original_data = [
            {"id": "p1", "amount_minor": 100, "currency": "EUR",
             "created_at": "2026-01-01T00:00:01Z", "status": "captured"},
        ]
        page = {
            "data": original_data,
            "next_cursor": None,
            "total": 1,
        }

        call_count = [0]

        class Conn(FakeConnection):
            def getresponse(self):
                call_count[0] += 1
                if call_count[0] == 1:
                    return FakeResponse(200, body=page, headers={"ETag": '"abc"'})
                else:
                    # Second call should include If-None-Match and get 304
                    req = self.last_request
                    self.assertEqual(req["headers"].get("If-None-Match"), '"abc"')
                    return FakeResponse(304, body=b"")

        with patch("vendorsync.meridian.HTTPConnection", Conn):
            # First call populates cache
            self.client.fetch_all_payments()
            # Second call should use ETag and get 304, returning cached data
            result = self.client.fetch_all_payments()

        self.assertEqual(len(result), 1)
        self.assertEqual(result[0]["id"], "p1")

    # ------------------------------------------------------------------
    # 6. test_create_payment_success
    # ------------------------------------------------------------------
    def test_create_payment_success(self):
        body = {"id": "pay_new", "amount_minor": 5000, "currency": "EUR"}

        class Conn(FakeConnection):
            def getresponse(self):
                req = self.last_request
                self.assertEqual(req["method"], "POST")
                self.assertEqual(req["headers"].get("Authorization"), "Bearer sk_test_meridian")
                self.assertEqual(req["headers"].get("Content-Type"), "application/json")
                self.assertEqual(req["headers"].get("Idempotency-Key"), "test-key-1")
                return FakeResponse(201, body=body)

        with patch("vendorsync.meridian.HTTPConnection", Conn):
            payment_id = self.client.create_payment(5000, "EUR", "test-key-1")

        self.assertEqual(payment_id, "pay_new")

    # ------------------------------------------------------------------
    # 7. test_create_payment_409_returns_existing_id
    # ------------------------------------------------------------------
    def test_create_payment_409_returns_existing_id(self):
        class Conn(FakeConnection):
            def getresponse(self):
                return FakeResponse(409, body={"error": "duplicate", "payment_id": "pay_existing"})

        with patch("vendorsync.meridian.HTTPConnection", Conn):
            payment_id = self.client.create_payment(5000, "EUR", "test-key-1")

        self.assertEqual(payment_id, "pay_existing")

    # ------------------------------------------------------------------
    # 8. test_timezone_normalization_and_utc_sorting
    # ------------------------------------------------------------------
    def test_timezone_normalization_and_utc_sorting(self):
        # These times in UTC order:
        # "2026-01-01T05:00:00-05:00" -> 10:00 UTC
        # "2026-01-01T07:30:00Z"     -> 07:30 UTC
        # "2026-01-01T10:00:00+02:00" -> 08:00 UTC
        # Sorted by UTC: 07:30Z, 08:00Z (was +02), 10:00Z (was -05)

        page = {
            "data": [
                {"id": "p_a", "amount_minor": 100, "currency": "EUR",
                 "created_at": "2026-01-01T10:00:00+02:00", "status": "captured"},
                {"id": "p_b", "amount_minor": 200, "currency": "EUR",
                 "created_at": "2026-01-01T07:30:00Z", "status": "captured"},
                {"id": "p_c", "amount_minor": 300, "currency": "EUR",
                 "created_at": "2026-01-01T05:00:00-05:00", "status": "captured"},
            ],
            "next_cursor": None,
            "total": 3,
        }

        class Conn(FakeConnection):
            def getresponse(self):
                return FakeResponse(200, body=page)

        with patch("vendorsync.meridian.HTTPConnection", Conn):
            result = self.client.fetch_all_payments()

        self.assertEqual(len(result), 3)
        # Correct UTC order: p_b (07:30Z), p_a (08:00Z), p_c (10:00Z)
        ids = [p["id"] for p in result]
        self.assertEqual(ids, ["p_b", "p_a", "p_c"])


